head.script:
scwin.screenId = "jldfil15301";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("lawTitle")); } },
        { childId: "__rb1", fn: function () { return "개정일 : " + String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("lawAmendDd"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — jldfil15301: 진입 키 poplaw 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil15301.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_lawItemList_2_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_lawItemList_2_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_lawItemList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_lawItemList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["lawItmStepTpNo"] == 4) { if (typeof scwin.lawItemView === 'function') { await scwin.lawItemView(r["lawItmSeq"]); } else { console.error('[sdd] 행 동작 미정의: scwin.lawItemView (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.lawItemView'); } return; }
        if (typeof scwin.viewAddRule === 'function') { await scwin.viewAddRule(); } else { console.error('[sdd] 행 동작 미정의: scwin.viewAddRule (열 부칙)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewAddRule'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_lawItemList_2.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_LawItemView
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_LawItemView = async function () {
    const sbmOptions = {
        id: "tx_fn_LawItemView",
        method: "post",
        action: "/support/popLaw.do",
        ref: "dma_LawItemViewReq",
        target: "dlt_lawItemList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil15301.tx_fn_LawItemView" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_ViewAddRule
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ViewAddRule = async function () {
    const sbmOptions = {
        id: "tx_fn_ViewAddRule",
        method: "post",
        action: "/support/popLaw.do",
        ref: "dma_ViewAddRuleReq",
        target: "dlt_lawItemList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil15301.tx_fn_ViewAddRule" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.lawItemView
 * @author Inswave
 * @date 2026. 09. 29
 * @param _lawItmSeq
 * @returns
 * @hidden N
*/
scwin.lawItemView = async function (_lawItmSeq) {
    /* sdd-asis-lifecycle:begin fn_LawItemView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.lawItemForm || { elements: [] });
    $c.util.getComponent('dma_LawItemViewReq').set('lawItmSeq', _lawItmSeq);
    $c.util.getComponent('dma_LawItemViewReq').set('method', "viewLawItemTemplete");
    frm.action = "popLaw.do";
    frm.target = "viewLawItem";
    $c.win.openPopup("", { id: "viewLawItem", scrollbars: true, resizable: false, width: "440", height: "500", type: "pageFramePopup" }, {});
    { const nr = await scwin.tx_fn_LawItemView(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil15302/jldfil15302.xml", { "lawItmSeq": _lawItmSeq, "method": "viewLawItemTemplete" }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.viewAddRule
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.viewAddRule = async function () {
    /* sdd-asis-lifecycle:begin fn_ViewAddRule — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.lawItemForm || { elements: [] });
    $c.util.getComponent('dma_LawItemViewReq').set('method', "viewAddRule");
    frm.action = "popLaw.do";
    frm.target = "viewLawItem";
    $c.win.openPopup("", { id: "viewLawItem", scrollbars: true, resizable: false, width: "440", height: "500", type: "pageFramePopup" }, {});
    { const nr = await scwin.tx_fn_ViewAddRule(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil15304/jldfil15304.xml", { "method": "viewAddRule" }); } };
    /* sdd-asis-lifecycle:end */
};
